def count_varied_windows(badges, k):
    counts = {}
    good = 0
    for i, b in enumerate(badges):
        counts[b] = counts.get(b, 0) + 1
        if i >= k:
            old = badges[i - k]
            counts[old] -= 1
            if counts[old] == 0:
                del counts[old]
        if i >= k - 1 and len(counts) == k:
            good += 1
    return good
